package com.vandorlabs.navigation;
/** Native and Forge observers share the same integer physical frame contract. */
public final class ObserverScaleTest {
 public static void main(String[] args){int cases=0;for(String id:new String[]{"standalone_dish","standalone_antenna"}){int base=id.equals("standalone_dish")?3:2,max=id.equals("standalone_dish")?16:8;need(ObserverScale.observer(id)&&ObserverScale.baseWidth(id)==base&&ObserverScale.maximumWidth(id)==max,"recognized observer endpoints");need(ObserverScale.width(id,0)==base,"absent width keeps released base");for(int width=base;width<=max;width++){int height=ObserverScale.height(id,width);need(ObserverScale.width(id,width)==width&&height==(id.equals("standalone_dish")?width:2*width),"proportional integral dimensions");need(width<=16&&height<=16,"existing Core axis bounds");need(Math.abs(ObserverScale.linearScale(id,width)-width/(double)base)<1e-12,"linear scale from physical width");cases++;}for(int width:new int[]{-1,base-1,max+1,Integer.MAX_VALUE}){boolean rejected=false;try{ObserverScale.width(id,width);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"invalid width refused "+width);}}need(!ObserverScale.observer("synthesis_tower")&&ObserverScale.baseWidth("synthesis_tower")==0,"builders not observers");boolean refused=false;try{ObserverScale.maximumWidth("survey_dish");}catch(IllegalArgumentException expected){refused=true;}need(refused,"obsolete raw design not silently assigned geometry");System.out.println("ObserverScaleTest PASS widths="+cases+" proportional/baseDefaults/16Axis/invalidBounds");}
 private static void need(boolean value,String message){if(!value)throw new AssertionError(message);}
}
